<script lang="ts">
 import {onMount,createEventDispatcher} from 'svelte';
 import qrcode from 'qrcode-generator';
 import {forumClient} from '../lib/forum/factory';
 import {NetworkClient,parsePeerInvite,reconcileSelections,buildPublicJobRequest,type PublicAnalysisKind,type LanState,type PeerInvite,type ParticipantInfo,type PublicSessionView,type PublicSearchHit,type PublishedSelection} from '../lib/forum/network';
 import {errorText,evidenceParts} from '../lib/forum/session-fence';
 import {kindLabels} from '../lib/forum/client';
 export let sessionId:string;export let eventId:string;export let running=false;export let active=true;
 const dispatch=createEventDispatcher<{created:{sessionId:string}}>();const client=new NetworkClient(forumClient.transport);const writable=forumClient.mode==='desktop';
 let open=false;let pane:'activity'|'sharing'|'pairing'='activity';let busy=false;let refreshing=false;let destroyed=false;let error='';let notice='';
 let state:LanState|null=null;let address='';let port=8743;let publicTitle='';let roomName='';let lifetime=60;let acceptedTrust=false;
 let grant:ParticipantInfo|null=null;let invitation:PeerInvite|null=null;let invitationText='';let incomingText='';let incoming:PeerInvite|null=null;let confirmedFingerprint='';let qr='';
 let selectedEvent=eventId;let rooms:PublicSessionView[]=[];let selections:PublishedSelection[]=[];let query='';let hits:PublicSearchHit[]|null=null;let generation=0;
 $: eventIds=[...new Set([eventId,...(state?.peers??[]).map(p=>p.session.event_id)])];
 $: qr=makeQr(grant?.url??'');
 function makeQr(url:string){if(!url)return '';try{const code=qrcode(0,'M');code.addData(url);code.make();return code.createDataURL(5,20);}catch{return '';}}
 const date=(value:number|null|undefined)=>value?new Date(value).toLocaleString():'尚未同步';
 function key(s:PublishedSelection){return `${s.owner_device_id}:${s.session_id}:${s.public_id}:${s.revision}`;}
 function pick(room:PublicSessionView,publicId:string,revision:number,checked:boolean){const value={owner_device_id:room.owner_device_id,session_id:room.session_id,public_id:publicId,revision};selections=checked?[...selections.filter(s=>key(s)!==key(value)),value]:selections.filter(s=>key(s)!==key(value));}
 async function refresh(){if(refreshing||destroyed)return;refreshing=true;const epoch=generation;try{const next=await client.state();const views=await client.sessions(selectedEvent);if(destroyed||epoch!==generation)return;state=next;if(grant&&!next.grants.some(g=>g.grant_id===grant?.grant_id))grant=null;if(!address&&next.certificate)address=next.certificate.address;rooms=views;const kept=reconcileSelections(selections,views);if(kept.length<selections.length)notice='有选中版本已变更、撤回或离线，已取消选择，请重新确认。';selections=kept;if(hits!==null)hits=hits.filter(hit=>views.some(room=>room.owner_device_id===hit.owner_device_id&&room.session_id===hit.session_id&&room.artifacts.some(a=>a.public_id===hit.public_id&&a.revision===hit.revision))).map(hit=>({...hit,stale:views.find(room=>room.session_id===hit.session_id)?.stale??true}));}catch(e){if(!destroyed&&epoch===generation){error=errorText(e);rooms=rooms.map(r=>({...r,stale:true}));selections=[];hits=null;}}finally{refreshing=false;}}
 async function act(work:()=>Promise<void>){if(!writable||busy)return;busy=true;error='';notice='';try{await work();}catch(e){if(!destroyed)error=errorText(e);}finally{if(!destroyed)busy=false;}}
 function eventChanged(){generation++;selections=[];rooms=[];hits=null;error='';void refresh();}
 function toggle(event:Event){open=(event.currentTarget as HTMLDetailsElement).open;if(open)void refresh();}
 function createCertificate(){void act(async()=>{const info=await client.certificate(address.trim());if(destroyed)return;state=await client.state();acceptedTrust=false;notice=`证书已保存：${info.ca_certificate_path}。请先在手机系统安装并信任此 CA。`;});}
 function start(){void act(async()=>{state=await client.start(address.trim(),port);notice='局域网 HTTPS 已启用。还未创建任何参会者访问凭据。';});}
 function stop(){void act(async()=>{state=await client.stop();grant=null;invitation=null;invitationText='';notice='局域网已关闭，访问凭据已撤销，对端同步已停止。';});}
 const publicRequest=()=>({session_id:sessionId,public_title:publicTitle.trim(),room_name:roomName.trim()});
 function participant(){void act(async()=>{if(grant)await client.revoke(grant.grant_id);grant=null;const result=await client.participant({...publicRequest(),ttl_ms:lifetime*60000});if(!destroyed)grant=result;});}
 function invite(){void act(async()=>{if(invitation)await client.revoke(invitation.invite_id);invitation=null;invitationText='';const result=await client.invite(publicRequest());if(!destroyed){invitation=result;invitationText=JSON.stringify(result,null,2);notice='此一次性邀请仅供另一台操作员电脑使用，5 分钟内有效。';}});}
 function parseInvite(){try{incoming=parsePeerInvite(incomingText);confirmedFingerprint='';error='';}catch(e){error=errorText(e);incoming=null;}}
 function pair(){if(!incoming)return;const saved=incoming;void act(async()=>{await client.pair(saved,confirmedFingerprint.trim());if(destroyed)return;incoming=null;incomingText='';confirmedFingerprint='';state=await client.state();selectedEvent=saved.source.event_id;generation++;await refresh();notice='已连接来源会场；当前旧会议仍属于原活动。需要同场汇总时，请将后续场次加入该活动。';});}
 function joinEvent(id:string){void act(async()=>{await forumClient.transport.call('join_forum_event',{eventId:id});notice='后续新场次将加入这个活动；已有会议的所属活动保持原样。';});}
 function revoke(id:string){void act(async()=>{await client.revoke(id);if(grant?.grant_id===id)grant=null;if(invitation?.invite_id===id){invitation=null;invitationText='';}notice='此访问已撤销。对方离线期间的旧副本，会在重连后更新撤回状态。';});}
 function disconnect(owner:string,session:string){void act(async()=>{await client.disconnect(owner,session);await refresh();});}
 function search(){void act(async()=>{const epoch=generation;const found=await client.search(selectedEvent,query.trim());if(!destroyed&&epoch===generation)hits=found;});}
 function createPublicAnalysis(kind:PublicAnalysisKind){void act(async()=>{const request=buildPublicJobRequest(kind,selectedEvent,sessionId,selections,rooms,crypto.randomUUID());await forumClient.createJob(request);if(!destroyed){notice=`${kind==='event_report'?'跨会场报告':'闭幕综述'}草稿已入队，完成后请在当前场次的任务/纪要页审核。`;dispatch('created',{sessionId});}});}
 async function copy(text:string){try{await navigator.clipboard.writeText(text);notice='已复制到剪贴板。';}catch{notice='无法自动复制，请选择文本复制。';}}
 onMount(()=>{const timer=window.setInterval(()=>{if(open&&active&&!busy)void refresh();},5000);return()=>{destroyed=true;generation++;window.clearInterval(timer);};});
</script>
<details class="network-panel" on:toggle={toggle}>
 <summary><span>活动与会场共享</span><small>双会场 · 参会者入口 · 闭幕综述</small><em>{state?.enabled?'HTTPS 已启用':'局域网默认关闭'}</em></summary>
 <div class="network-content">
  <nav aria-label="活动与共享"><button class:selected={pane==='activity'} on:click={()=>pane='activity'}>活动总览</button><button class:selected={pane==='sharing'} on:click={()=>pane='sharing'}>参会者入口</button><button class:selected={pane==='pairing'} on:click={()=>pane='pairing'}>连接另一会场</button></nav>
  {#if !writable}<p class="note">这是合成数据界面预览。网络、配对与发布操作仅在桌面应用中可用。</p>{/if}
  {#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="notice" role="status">{notice}</p>{/if}{#if state?.notice}<p class="note">{state.notice}</p>{/if}
  {#if pane==='activity'}
   <div class="activity-top"><label>活动<select bind:value={selectedEvent} on:change={eventChanged}>{#each eventIds as id}<option value={id}>{id===eventId?'当前场次活动':'已连接活动'} · {id.slice(0,8)}</option>{/each}</select></label><button disabled={!writable||refreshing} on:click={refresh}>刷新</button>{#if selectedEvent!==eventId}<button disabled={!writable||busy||running} on:click={()=>joinEvent(selectedEvent)}>将后续场次加入此活动</button>{/if}</div>
   <form class="search" on:submit|preventDefault={search}><input aria-label="检索已发布资料" bind:value={query} maxlength="128" placeholder="检索已发布的摘要与公开引用"/><button disabled={!writable||busy||!query.trim()}>检索</button><button type="button" on:click={()=>hits=null}>浏览全部</button></form>
   {#if hits!==null}<div class="search-results">{#each hits as hit}{@const parts=evidenceParts(hit.text,hit.match_start_utf8,hit.match_end_utf8,new TextDecoder().decode(new TextEncoder().encode(hit.text).slice(hit.match_start_utf8,hit.match_end_utf8)))}<article><strong>{hit.title} · V{hit.revision}</strong><small>{hit.session_id.slice(0,8)}{hit.stale?' · 离线旧副本':''}</small><p>{#if parts}{parts.before}<mark>{parts.quote}</mark>{parts.after}{:else}{hit.text}{/if}</p></article>{:else}<p class="note">没有匹配的公开资料。</p>{/each}</div>
   {:else}<div class="room-grid">{#each rooms as room (room.session_id)}<article class:stale={room.stale}><header><div><small>{room.local?'本机':'对端'} · {room.room_name}</small><h3>{room.title}</h3></div><span>{room.stale?'离线 · 旧副本':'已同步'}</span></header><p class="sync">{room.local?'独立本地记录':`最后同步：${date(room.last_sync_at_ms)}`} · {room.artifacts.length} 项公开成果</p>{#if room.stale}<p class="note">离线期间无法确认新撤回，当前副本不参与生成新的跨会场报告或闭幕综述。</p>{/if}{#each room.artifacts as artifact (artifact.public_id)}<label class="public-item"><input type="checkbox" disabled={!writable||room.stale||busy} checked={selections.some(s=>s.public_id===artifact.public_id&&s.session_id===room.session_id&&s.revision===artifact.revision)} on:change={e=>pick(room,artifact.public_id,artifact.revision,e.currentTarget.checked)}/><span><small>{kindLabels[artifact.kind]} · V{artifact.revision}</small><strong>{artifact.title}</strong><span class="public-text">{artifact.text}</span></span></label>{:else}<p class="note">此场次暂无已审核发布内容。</p>{/each}</article>{:else}<p class="note">该活动暂无可浏览的公开会场。</p>{/each}</div>{/if}
   <div class="closing-bar"><p>已选择 {selections.length} 个精确发布版本。报告与闭幕综述先生成私有草稿，审核后才可展示；已发布闭幕稿可朗读。</p><button disabled={!writable||busy||!selections.length||!selections.some(s=>s.session_id===sessionId)} on:click={()=>createPublicAnalysis('event_report')}>生成跨会场报告</button><button class="primary" disabled={!writable||busy||!selections.length||!selections.some(s=>s.session_id===sessionId)} on:click={()=>createPublicAnalysis('closing_brief')}>生成闭幕综述</button><small>选择中需包含当前场次。主持人问题始终只在操作台可见。</small></div>
  {:else}
   <div class="network-columns"><section class="setup"><h3>局域网 HTTPS</h3><p class="note">使用本机在会场网络中的 IP。网络或 IP 改变后需重新生成证书。</p><div class="form-row"><label>本机局域网 IP<input bind:value={address} placeholder="192.168.1.20" disabled={!!state?.enabled}/></label><label class="port">端口<input type="number" min="1024" max="65535" bind:value={port} disabled={!!state?.enabled}/></label></div><button disabled={!writable||busy||!!state?.enabled||!address.trim()} on:click={createCertificate}>生成本活动证书</button>
    {#if state?.certificate}<div class="certificate"><p>CA 文件：<code>{state.certificate.ca_certificate_path}</code></p><p>CA SHA-256：<code>{state.certificate.ca_sha256}</code></p><p>服务证书 SHA-256：<code>{state.certificate.certificate_sha256}</code></p><p>服务证书有效期 {state.certificate.expires_days} 天。重启应用后需重新启用共享。</p></div><details class="trust-help"><summary>手机如何安装证书</summary><ol><li>通过 AirDrop、数据线或设备管理分发上面的 CA 文件，核对显示的指纹。</li><li>iPhone：在“设置”安装描述文件，再到“通用 → 关于本机 → 证书信任设置”开启此根证书的完全信任。</li><li>Android：在系统安全设置中安装 CA 证书。不同厂商路径可能不同；受管理设备须由管理员部署。</li><li>手机连接同一会场 Wi-Fi，扫码后应直接显示 HTTPS 页面。如果出现证书警告，先修复信任、IP 或证书配置。</li></ol></details><label class="check"><input type="checkbox" bind:checked={acceptedTrust}/>我已核对 IP 和证书部署方式</label>{/if}
    <div class="actions">{#if state?.enabled}<button on:click={stop} disabled={busy}>关闭共享并撤销访问</button><span class="endpoint">{state.endpoint}</span>{:else}<button class="primary" on:click={start} disabled={!writable||busy||!state?.certificate||!acceptedTrust}>启用局域网 HTTPS</button>{/if}</div>
   </section><section><h3>{pane==='sharing'?'当前场次的参会者入口':'向另一台电脑发出邀请'}</h3><p class="note">这些名称将随邀请提供给对端。只同步人工发布的文本和公开引用。</p><label>允许公开的场次名<input bind:value={publicTitle} maxlength="150" placeholder="请填写审核后的公开场次名"/></label><label>允许公开的会场名<input bind:value={roomName} maxlength="60" placeholder="例如：A 会场"/></label>
    {#if pane==='sharing'}<label>访问有效期<select bind:value={lifetime}><option value={15}>15 分钟</option><option value={60}>1 小时</option><option value={240}>4 小时</option><option value={480}>8 小时</option></select></label><button class="primary" disabled={!writable||busy||!state?.enabled||!publicTitle.trim()||!roomName.trim()} on:click={participant}>创建只读二维码</button>{#if grant}<div class="qr-result">{#if qr}<img src={qr} alt="此场次限时只读访问二维码" width="245" height="245"/>{/if}<p>有效至 {date(grant.expires_at_ms)}</p><div class="actions"><button on:click={()=>copy(grant!.url)}>复制访问链接</button><button disabled={busy} on:click={()=>revoke(grant!.grant_id)}>撤销入口</button></div></div>{/if}
    {:else}<button class="primary" disabled={!writable||busy||!state?.enabled||!publicTitle.trim()||!roomName.trim()} on:click={invite}>创建一次性会场邀请</button>{#if invitation}<textarea readonly value={invitationText} aria-label="会场邀请内容" rows="7"></textarea><p class="note">仅交给另一台操作员电脑。邀请 5 分钟有效，使用一次后转为最长 8 小时的独立只读配对。</p><div class="actions"><button on:click={()=>copy(invitationText)}>复制邀请</button><button disabled={busy} on:click={()=>revoke(invitation!.invite_id)}>撤销此邀请/配对</button></div>{/if}{/if}
   </section></div>
   {#if pane==='pairing'}<section class="receive"><h3>接收另一会场邀请</h3><textarea bind:value={incomingText} on:input={()=>{incoming=null;confirmedFingerprint='';}} rows="4" placeholder="粘贴另一台操作员电脑提供的邀请" aria-label="接收邀请"></textarea><button disabled={!writable||busy||!incomingText.trim()} on:click={parseInvite}>检查邀请</button>{#if incoming}<p>{incoming.source.room_name} · {incoming.source.title}<br/>活动 {incoming.source.event_id}</p><p class="fingerprint">请在来源电脑上核对服务证书指纹：<code>{incoming.certificate_sha256}</code></p><label>输入已核对的完整指纹<input bind:value={confirmedFingerprint} autocomplete="off" spellcheck="false" placeholder="64 位 SHA-256"/></label><button class="primary" disabled={busy||confirmedFingerprint.trim()!==incoming.certificate_sha256} on:click={pair}>确认身份并连接</button>{/if}
    {#each state?.peers??[] as peer}<div class="peer-row"><div><strong>{peer.session.room_name} · {peer.session.title}</strong><small>{peer.stale?'离线 / 需要重新配对':'正在同步'} · 最后同步 {date(peer.last_sync_at_ms)}</small></div><button disabled={busy} on:click={()=>disconnect(peer.session.owner_device_id,peer.session.session_id)}>停止同步</button>{#if peer.session.event_id!==eventId}<button disabled={busy||running} on:click={()=>joinEvent(peer.session.event_id)}>后续场次加入该活动</button>{/if}</div>{/each}
   </section>{/if}
  {/if}
  {#if pane!=='activity'&&state?.grants.length}<section class="receive"><h3>已发出的访问权限</h3><p class="note">切换场次后仍可在此撤销旧入口；这里不显示访问凭据。</p>{#each state.grants as access}<div class="peer-row"><div><strong>{access.source.room_name} · {access.source.title}</strong><small>{access.kind==='participant'?'参会者只读入口':access.kind==='invite'?'一次性会场邀请':'已使用的会场配对'} · 有效至 {date(access.expires_at_ms)}</small></div><button disabled={busy} on:click={()=>revoke(access.grant_id)}>撤销权限</button></div>{/each}</section>{/if}
 </div>
</details>
<style>
 .network-panel{border:1px solid #d5dae2;background:#fafbfd;margin-bottom:22px}.network-panel>summary{display:flex;gap:16px;align-items:center;cursor:pointer;padding:15px 18px;font-size:13px;font-weight:650;list-style:none}.network-panel>summary:before{content:'+';font-size:18px;color:#728099}.network-panel[open]>summary:before{content:'−'}summary small{font-size:11px;color:#738095;font-weight:400}summary em{font-style:normal;font-weight:400;font-size:10px;color:#657086;margin-left:auto}.network-content{border-top:1px solid #d9dfe8;padding:20px}nav{display:flex;gap:22px;border-bottom:1px solid #dae0e8;margin-bottom:18px}nav button{border:0;background:none;padding:10px 0;color:#7d8796}nav button.selected{color:#3d527b;border-bottom:2px solid #596e96}button{background:white;border:1px solid #cbd2dd;padding:8px 11px;cursor:pointer}button.primary{background:#435777;border-color:#435777;color:white}button:disabled{opacity:.4;cursor:default}h3{font-size:15px;margin:0 0 12px}.note,.notice,.error{font-size:12px;line-height:1.85;overflow-wrap:anywhere}.note{color:#738095}.notice{background:#edf4ef;color:#47644f;padding:10px}.error{background:#fff0ed;color:#9b493b;padding:10px}label{font-size:11px;display:block;color:#657187;margin:12px 0}input:not([type=checkbox]),select,textarea{width:100%;box-sizing:border-box;font:inherit;font-size:12px;border:1px solid #cbd3df;border-radius:0;background:white;padding:9px;margin-top:7px;color:#283349}textarea{resize:vertical;min-height:72px;font-family:ui-monospace,monospace;font-size:11px}input[type=checkbox]{width:14px;height:14px;accent-color:#526b91;flex-shrink:0}.check{display:flex;gap:7px;align-items:center}.network-columns{display:grid;grid-template-columns:1fr 1fr;gap:30px}.network-columns>section{min-width:0}.network-columns>section+section{border-left:1px solid #dce1e8;padding-left:30px}.form-row{display:flex;gap:12px}.form-row label{flex:1}.form-row .port{flex:0 0 100px}.certificate{font-size:10px;line-height:1.75;margin-top:15px;color:#7b8595;background:#eff2f6;padding:9px 12px}code{display:block;overflow-wrap:anywhere;white-space:pre-wrap;font-size:10px}.trust-help{font-size:11px;line-height:1.85;margin:14px 0;color:#607086}.trust-help summary{cursor:pointer;font-weight:600}.trust-help ol{padding-left:20px}.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:12px}.endpoint{font-size:11px;color:#5d7290}.qr-result{margin-top:20px;padding:18px;background:white;text-align:center;border:1px solid #e1e5eb}.qr-result img{max-width:100%;height:auto;image-rendering:pixelated}.qr-result p{font-size:11px;color:#778297}.qr-result .actions{justify-content:center}.receive{border-top:1px solid #d7dee9;margin-top:26px;padding-top:24px}.receive>p{font-size:12px;line-height:1.7}.fingerprint{background:#f0f3f8;padding:10px}.peer-row{display:flex;gap:10px;align-items:center;border-bottom:1px solid #e0e5ec;padding:15px 0}.peer-row>div{flex:1;min-width:0}.peer-row strong{display:block;font-size:12px}.peer-row small{font-size:10px;color:#7b8798;display:block;margin-top:7px}.activity-top{display:flex;align-items:flex-end;gap:12px}.activity-top label{flex:1;max-width:400px;margin:0}.activity-top button{margin-bottom:0}.search{display:flex;align-items:center;gap:8px;margin:18px 0}.search input{margin:0;flex:1}.room-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(330px,100%),1fr));gap:15px}.room-grid>article,.search-results>article{padding:18px;border:1px solid #d8dfe8;background:white;min-width:0}.room-grid>article.stale{border-color:#cfbfa7;background:#fcfaf6}.room-grid header{display:flex;justify-content:space-between;gap:12px}.room-grid header small{font-size:10px;color:#8a95a6}.room-grid header h3{margin:7px 0 0;overflow-wrap:anywhere}.room-grid header>span{font-size:10px;color:#5e8469;white-space:nowrap}.stale header>span{color:#a17846}.sync{font-size:10px;color:#8a93a0}.public-item{display:flex;align-items:flex-start;gap:8px;padding-top:14px;margin-top:14px;border-